1: // Evaluation source only. Inputs are finite-number arrays; cutoffs are finite.
2: // The reference contract defines the mean of an empty array as zero.
3: // The candidate functions have not been approved for implementation or execution.
4: export const reference = {
5:   keepAtLeast(values, cutoff) {
6:     return values.filter(value => value >= cutoff);
7:   },
8:   sum(values) {
9:     return values.reduce((total, value) => total + value, 0);
10:   },
11:   mean(values) {
12:     return values.length === 0 ? 0 : this.sum(values) / values.length;
13:   },
14: };
